class AppShell extends StatefulWidget { const AppShell({super.key}); @override State<AppShell> createState()=>_AppShellState(); }
class _AppShellState extends State<AppShell> {
  int tab=0; String role='Customer';
  @override Widget build(BuildContext context) {
    final pages = role=='Customer' ? [const HomeScreen(),const GroceryScreen(),const SearchScreen(),const AccountScreen()] : role=='Restaurant Partner' ? [const PartnerScreen(),const PartnerMenuScreen(),const PartnerAnalyticsScreen(),const PartnerStoreScreen()] : role=='Rider' ? [const RiderScreen(),const RiderDeliveriesScreen(),const RiderEarningsScreen(),const RiderProfileScreen()] : [const AdminScreen(),const AdminDispatchScreen(),const AdminMerchantsScreen(),const AdminReportsScreen()];
    final labels=role=='Customer'?['Food','Grocery','Search','Account']:role=='Restaurant Partner'?['Orders','Menu','Analytics','Store']:role=='Rider'?['Shift','Deliveries','Earnings','Profile']:['Overview','Dispatch','Merchants','Reports'];
    final icons=role=='Customer'?[Icons.restaurant,Icons.shopping_basket,Icons.search,Icons.person_outline]:role=='Restaurant Partner'?[Icons.receipt_long,Icons.menu_book,Icons.bar_chart,Icons.storefront]:role=='Rider'?[Icons.map_outlined,Icons.delivery_dining,Icons.account_balance_wallet,Icons.person]:[Icons.dashboard,Icons.map,Icons.verified_user,Icons.analytics];
    return Scaffold(appBar: AppBar(title: Row(children:[const Text('food',style:TextStyle(fontWeight:FontWeight.w900,color:ink)),const Text('cat',style:TextStyle(fontWeight:FontWeight.w900,color:pink)),const Spacer(),DropdownButtonHideUnderline(child:DropdownButton<String>(value:role,items:['Customer','Restaurant Partner','Rider','Admin'].map((e)=>DropdownMenuItem(value:e,child:Text(e,style:const TextStyle(fontSize:12)))).toList(),onChanged:(v){setState((){role=v!;tab=0;});})), if(role=='Customer') Consumer<CartProvider>(builder:(c,cart,_)=>IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const CartScreen())),icon:Badge(label:Text('${cart.count}'),isLabelVisible:cart.count>0,child:const Icon(Icons.shopping_bag_outlined))))]),),body:IndexedStack(index:tab,children:pages),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:List.generate(4,(i)=>NavigationDestination(icon:Icon(icons[i]),label:labels[i]))));
  }
}

class HomeScreen extends StatefulWidget { const HomeScreen({super.key}); @override State<HomeScreen> createState()=>_HomeScreenState(); }
