ld)),subtitle:const Text('★ 4.8  •  25–35 min  •  Delivery from Rs. 99'),trailing:const Icon(Icons.chevron_right),onTap:()=>setState(()=>category='All')))),const SizedBox(height:16),_SectionTitle('Popular dishes',''),...products.map((p)=>ProductTile(product:p)),]));
}

